export function localChapterCard(s,id,{E,esc,picture,inPerson=false}){
 const v=E.localStory(s,id);if(!v)return '';const r=v.record;
 if(v.complete)return `<article class="local-chapter completed"><small>FIVE CHAPTERS SHARED ✓</small><h3>${esc(v.name)}</h3><p>${esc(v.person)} remembers the choices you made together: ${esc(v.choices.find(c=>c.id===r.choice).name.toLowerCase())}.</p><details><summary>Your story memories</summary>${r.history.map(h=>`<p>Day ${h.day} · ${esc(h.title)}${h.productId?' · '+esc(E.byId(h.productId).name):''}</p>`).join('')}</details></article>`;
 const heading=`<small>${esc(v.person.toUpperCase())}’S STORY · CHAPTER ${v.stage+1} / ${E.LOCAL_STORY_CHAPTERS}</small><h3>${esc(v.active?v.chapter.title:v.name)}</h3>`;
 if(v.waiting)return `<article class="local-chapter">${heading}<p>A good place to leave the conversation. Your next chapter arrives on Day ${r.readyDay}.</p><span class="story-wait">Tomorrow, another little story.</span></article>`;
 if(!v.active)return `<article class="local-chapter">${heading}<p>${esc(r?v.chapter.text:v.intro)}</p>${inPerson?r?`<button class="button orange wide" data-action="local-story-begin" data-id="${id}">Begin chapter ${v.stage+1}</button>`:`<div class="story-choices">${v.choices.map(c=>`<button data-action="local-story-begin" data-id="${id}" data-choice="${c.id}"><strong>${esc(c.name)}</strong><span>${esc(c.text)}</span></button>`).join('')}</div>`:`<button class="button secondary wide" data-action="local-visit" data-id="${id}">${r?'Continue with':'Meet'} ${esc(v.person)} ↗</button>`}<p class="story-note">Five chapters, at least five days. No deadline; completed actions after accepting count. Your choice shapes the later chapters.</p></article>`;
 const gifts=v.chapter.gift?E.localGiftCandidates(s):[];
 return `<article class="local-chapter">${heading}<p class="story-dialogue">${esc(v.chapter.text)}</p><div class="story-progress"><span>${v.done} / ${v.total} steps</span><span>${E.money(v.chapter.cash)} + ${v.chapter.xp} XP</span></div><ol class="story-tasks">${v.tasks.map(t=>`<li class="${t.count>=t.target?'done':''}"><span>${t.count>=t.target?'✓':'○'}</span><span>${esc(t.label)}<small>${t.count} / ${t.target}</small></span></li>`).join('')}</ol>${v.chapter.gift?`<p class="story-note">Buy after beginning this chapter. Try-ons keep tags intact. Worn, checked, returned or delivered items cannot be given. Gift purchases may come from any unlocked mall.</p>${inPerson&&gifts.length?gifts.map(i=>{const p=E.byId(i.productId);return `<div class="story-gift"><div class="mini-art">${picture(p)}</div><span><strong>${esc(p.name)}</strong><small>${E.money(i.total)} + $2 wrap reimbursement</small></span><button class="button orange" data-action="local-story-claim" data-id="${id}" data-item="${i.id}">Give to Maya</button></div>`;}).join(''):`<button class="button secondary wide" data-action="venue" data-id="services">Guest services · gift wrapping ↗</button><button class="text-button" data-action="local-gift-browse">Browse qualifying real models ↗</button>`}`:''}${v.ready?inPerson&&!v.chapter.gift?`<button class="button orange wide" data-action="local-story-claim" data-id="${id}">Share this chapter · ${E.money(v.chapter.cash)} + ${v.chapter.xp} XP</button>`:!inPerson?`<button class="button orange wide" data-action="local-visit" data-id="${id}">Share this chapter with ${esc(v.person)} ↗</button>`:'':`<button class="button orange wide" data-action="local-story-follow" data-id="${id}">Follow this chapter ↗</button>`}<p class="story-note">This chapter began at ${esc(E.mallById(r.mallId).name)}. Its visit, label and activity steps count at that mall and carry across days.</p>${s.communityFocus===id?'<span class="story-wait">Tracked above the mall</span><button class="text-button" data-action="track-story">Track my main story instead</button>':`<button class="text-button" data-action="local-story-track" data-id="${id}">Track this chapter above the mall</button>`}</article>`;
}
export function communityBoard(s,ctx){return `<details class="community-board" ${s.localStories.some(v=>v.active)?'open':''}><summary><span><small>LOCAL STORIES · ${ctx.E.LOCAL_STORIES.length*ctx.E.LOCAL_STORY_CHAPTERS} OPTIONAL MISSIONS</small><strong>People make a place.</strong></span><span>${s.localStories.reduce((n,v)=>n+v.stage,0)} / ${ctx.E.LOCAL_STORIES.length*ctx.E.LOCAL_STORY_CHAPTERS} chapters · Open stories ⌄</span></summary><p>Listen, choose a direction, and return another day. Five familiar faces have afternoons to share.</p><div class="local-story-grid">${ctx.E.LOCAL_STORIES.map(v=>localChapterCard(s,v.id,ctx)).join('')}</div></details>`;}
export function wrappingDesk(s,{E,esc,picture},style){const available=E.wrappablePurchases(s),wrapped=E.owned(s).filter(i=>i.giftWrap&&!i.checked);return `<div class="modal-body wrapping-desk"><p>Choose a real purchase and paper for it. Wrapping costs <strong>$2 and 6 game minutes</strong>. Tags stay intact; unwrap here before wearing, using or returning. The wrapping fee is not refundable.</p><div class="wrap-papers" role="group" aria-label="Gift wrapping paper">${E.GIFT_WRAPS.map(w=>`<button data-action="wrap-style" data-id="${w.id}" aria-pressed="${style===w.id}"><i style="background:${w.color}"></i>${esc(w.name)}</button>`).join('')}</div><h3>A purchase to wrap</h3>${available.map(i=>{const p=E.byId(i.productId);return `<article class="wrap-purchase"><div class="mini-art">${picture(p)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.brand)} · ${E.money(i.total)} receipt</small><button class="button orange" data-action="wrap-gift" data-id="${i.id}">Wrap this purchase · $2</button></div></article>`;}).join('')||'<p class="hint">Bring an unused purchase with tags or packaging intact. Collect checked packages first. Food and drinks are not gift-wrapped.</p>'}${wrapped.length?`<h3>Your wrapped purchases</h3>${wrapped.map(i=>`<article class="package-row"><span>🎁 ${esc(E.byId(i.productId).name)}<small>${esc(E.GIFT_WRAPS.find(w=>w.id===i.giftWrap.style).name)}</small></span><button class="button secondary" data-action="unwrap-gift" data-id="${i.id}">Unwrap · free · 1 min</button></article>`).join('')}`:''}<button class="text-button" data-action="guest-services">Back to guest services</button></div>`;}
